from html import escape as H

def detail(r):
 vid=r['video_id'];title=r.get('display_title') or r['title'].split(' | ')[0]
 intro=r.get('editorial_summary') or 'Watch the play, follow the shot, and see the full moment with HoopCut.'
 return f'''<main id="main"><nav class="video-crumb" aria-label="Breadcrumb"><a href="/">HoopCut</a><span>/</span><a href="/videos">On the court</a></nav><section class="video-hero"><div class="video-copy"><p class="video-kicker">HoopCut / On the court</p><h1>{H(title)}</h1><p class="video-intro">{H(intro)}</p><div class="video-facts"><span>Pickup basketball</span><span>{round(r['duration_seconds'])} seconds</span><span>Shot Tracer</span></div><div class="video-actions"><a class="primary" href="https://www.youtube.com/shorts/{vid}">Watch on YouTube ↗</a><a class="secondary" href="/">Explore HoopCut →</a></div><div class="video-source">Original footage by <a href="{H(r['source_url'],quote=True)}">@cantfakethetape ↗</a><br>Cut and traced with HoopCut.</div></div><figure class="video-screen"><div class="video-frame"><iframe src="https://www.youtube-nocookie.com/embed/{vid}?rel=0" title="{H(r['title'],quote=True)}" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe></div><figcaption><span>HoopCut original edit</span><span>9:16 / HD</span></figcaption></figure></section><section class="video-notes"><h2>Inside the clip</h2><p>{H(r.get('editorial_notes') or r['scene_notes'])}</p></section><section class="video-more"><p class="video-kicker">Keep your game in focus</p><h2>Make more of your footage.</h2><div class="video-related"><a href="/blog/how-to-add-shot-tracer-to-basketball-video"><small>Shot Tracer</small><strong>Follow the arc.<br>Review every shot. ↗</strong></a><a href="/blog/how-to-make-a-basketball-highlight-video"><small>Editing guide</small><strong>Turn game footage<br>into a highlight reel. ↗</strong></a><a href="/tools"><small>Free tools</small><strong>Plan the shots.<br>Keep the best moments. ↗</strong></a></div></section></main>'''

def index(records):
 cards=''
 for r in records:
  vid=r['video_id'];title=r.get('display_title') or r['title'].split(' | ')[0]
  cards+=f'<article class="video-tile"><a href="/videos/{vid}"><img src="/assets/videos/{vid}.jpg" alt="{H(title,quote=True)}" width="1080" height="1920"><div class="tile-copy"><p class="video-kicker">Pickup basketball · {round(r["duration_seconds"])} sec</p><h2>{H(title)}</h2><p>Watch the clip →</p></div></a></article>'
 return '<main id="main"><nav class="video-crumb"><a href="/">HoopCut</a><span>/</span><span>Videos</span></nav><p class="video-kicker">HoopCut / On the court</p><h1>The game moves fast.<br>Keep the good parts.</h1><p class="index-lede">Basketball moments, cut down to the action. Watch the plays and follow each shot with HoopCut.</p><section class="video-grid" aria-label="Basketball videos">'+cards+'</section></main>'
